import React from 'react';
import { StoryStack } from '@fiverr-private/storybook_helpers';
import * as logos from '..';
import type { FiverrLogosType } from '../../types';

interface LogoTypeDemo extends Pick<FiverrLogosType, 'size'> {
  logoName: keyof typeof logos;
}

const Demo = ({ logoName, size }: LogoTypeDemo) => {
  const Logo = logos[logoName];
  return (
    <StoryStack backgroundColor={logoName.endsWith('LightLogo') ? 'grey_1200' : 'white'} padding="3">
      <Logo size={size} />
    </StoryStack>
  );
};

export default Demo;
